#!/usr/bin/env bash
# Adds real file logging to the Agent - a running-but-silently-failed
# Windows service (exactly what you're seeing: STATE=RUNNING, exit code 0,
# no crash, but instance_id never gets set) has NOWHERE for its log output
# to go, since logging.basicConfig() defaulted to stderr and a Windows
# service has no console attached at all. Whatever is actually going wrong
# with registration has been completely invisible until now.
#
# Fixed: setup_logging() now always writes to a rotating file
# (agent.log, next to settings.json - so on Windows that is
# C:\ProgramData\OpsLabAgent\agent.log) in addition to the console.
# Verified for real: ran setup_logging() and confirmed a real log file
# with real content gets created, before shipping this.
#
# This does not fix the underlying registration problem by itself - it
# gives us the actual error message so we can. Run from inside
# /root/admin_panel.
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")"

echo "==> Rewriting app/static/installers/opslab-agent.tar.gz (adds file logging)"
base64 -d > app/static/installers/opslab-agent.tar.gz << 'B64_EOF_MARKER'

B64_EOF_MARKER

echo "==> Verifying the tarball is valid and contains the fix"
tar -tzf app/static/installers/opslab-agent.tar.gz > /dev/null && echo "    tarball is readable"
mkdir -p /tmp/verify_fix_$$
tar -xzf app/static/installers/opslab-agent.tar.gz -C /tmp/verify_fix_$$
if grep -q "RotatingFileHandler" /tmp/verify_fix_$$/agent/main.py; then
    echo "    Confirmed: file-logging fix is present."
else
    echo "    ERROR: fix not found in the extracted tarball!"
    rm -rf /tmp/verify_fix_$$
    exit 1
fi
rm -rf /tmp/verify_fix_$$

echo ""
echo "Done. Restart the app:"
echo "    pkill -f 'admin_panel/run.py'"
echo "    cd /root/admin_panel && source venv/bin/activate && nohup python run.py > /root/admin_panel/app.log 2>&1 &"
echo ""
echo "Then on the Windows machine, do a clean reinstall (same as last time) so it"
echo "downloads this updated tarball, then check the new log file it will finally write:"
echo "    sc.exe stop OpsLabAgent"
echo "    sc.exe delete OpsLabAgent"
echo '    Remove-Item "C:\Program Files\OpsLabAgent" -Recurse -Force'
echo "    (re-run the install command from the instances page)"
echo '    Get-Content "C:\ProgramData\OpsLabAgent\agent.log" -Tail 30'
